package br.com.confirmacao.auth.application;import br.com.confirmacao.user.infrastructure.UserRepository;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.Locale;
@Service public class AuthService{private final UserRepository users;private final PasswordEncoder passwords;private final TokenService tokens;public AuthService(UserRepository u,PasswordEncoder p,TokenService t){users=u;passwords=p;tokens=t;}@Transactional(readOnly=true)public AuthenticationResult authenticate(String e,String p){var u=users.findByEmailIgnoreCase(e.trim().toLowerCase(Locale.ROOT)).filter(x->x.isActive()&&passwords.matches(p,x.getPasswordHash())).orElseThrow(InvalidCredentialsException::new);return new AuthenticationResult(tokens.generate(u),tokens.expirationSeconds(),u);}}
